import { messages, resolveLocale } from "@school/i18n";
import { bffProblem } from "@/lib/bff";
import { checkOrigin } from "@/lib/origin";

/** Locale for server-generated messages, from Accept-Language. */
export function localeFromRequest(request: Request) {
  return resolveLocale(
    (request.headers.get("accept-language") ?? "").split(",").map((part) => part.split(";")[0] ?? ""),
  );
}

const TITLES = {
  bff_forbidden_origin: "bffForbiddenOrigin",
  bff_bad_request: "bffBadRequest",
  bff_not_found: "bffNotFound",
} as const;

/** An RFC 9457 problem generated by the web server itself (not the API). */
export function problemResponse(
  request: Request,
  code: string,
  status: number,
  init: { headers?: HeadersInit } = {},
): Response {
  const { errors } = messages[localeFromRequest(request)];
  const key = (TITLES as Record<string, keyof typeof errors>)[code];
  const title = key ? errors[key] : status === 404 ? errors.bffNotFound : errors.bffUnavailable;
  const headers = new Headers(init.headers);
  headers.set("content-type", "application/problem+json");
  headers.set("cache-control", "no-store");
  return Response.json(bffProblem(code, status, title), { status, headers });
}

/** 403 `bff_forbidden_origin` unless a mutating request comes from our own origin. */
export function guardOrigin(request: Request): Response | null {
  const verdict = checkOrigin({
    method: request.method,
    requestUrl: request.url,
    headers: request.headers,
    appOrigin: process.env.APP_ORIGIN,
  });
  return verdict.ok ? null : problemResponse(request, "bff_forbidden_origin", 403);
}
